    memset(pt, 0x5a, N);
    uint8_t iv[16]={0}; for(int i=0;i<12;i++) iv[i]=i; iv[15]=2;
    struct timespec t0,t1;
    clock_gettime(CLOCK_MONOTONIC,&t0);
    ctr(pt, ct, N/16, rk, rounds, _mm_loadu_si128((const __m128i*)iv));
    clock_gettime(CLOCK_MONOTONIC,&t1);
    double dt=(t1.tv_sec-t0.tv_sec)+(t1.tv_nsec-t0.tv_nsec)/1e9;
    printf("ctr: %.4fs %.2f GB/s\n", dt, N/dt/1e9);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_128_ctr(), NULL, key, iv);
    uint8_t *ref = malloc(N); int outlen;
    clock_gettime(CLOCK_MONOTONIC,&t0);
    EVP_EncryptUpdate(ctx, ref, &outlen, pt, N);
    clock_gettime(CLOCK_MONOTONIC,&t1);
