void ctr_aes_v(const uint8_t*,uint8_t*,size_t,const void*,uint8_t[16]);
void gcm_ghash_avx(uint64_t Xi[2], const void*, const uint8_t*, size_t);
void gcm_init_avx(void*, const void*);
void aesni_encrypt(const uint8_t*,uint8_t*,const void*);

#define NC 32
typedef struct { const uint8_t *in; uint8_t *out; size_t blocks; const void *key; uint8_t counter[16]; void *Htable; uint8_t Xi[16]; } chunk_t;
static chunk_t chunks[NC];
static atomic_int ctr_head, ctr_done_count, ghash_head;
static atomic_int phase; /* 0 idle, 1 run, 2 exit */
static int CT, GT;

static void *ctr_thread(void *arg){
    int myphase = 0;
    for(;;){
        int p;
        while((p = atomic_load(&phase)) == myphase) ; /* spin for new phase */
        myphase = p;
        if(p == 2) return NULL;
        for(;;){
            int i = atomic_fetch_add(&ctr_head, 1);
            if(i >= NC) break;
            ctr_aes_v(chunks[i].in, chunks[i].out, chunks[i].blocks, chunks[i].key, chunks[i].counter);
            atomic_fetch_add(&ctr_done_count, 1);
        }
    }
}
static void *ghash_thread(void *arg){
    int myphase = 0;
    for(;;){
        int p;
        while((p = atomic_load(&phase)) == myphase) ;
        myphase = p;
        if(p == 2) return NULL;
        for(;;){
            int done = atomic_load(&ctr_done_count);
            int i = atomic_load(&ghash_head);
            if(i >= NC) break;
            if(i >= done) continue; /* spin until ctr finishes this chunk */
            if(atomic_compare_exchange_weak(&ghash_head, &i, i+1)){
                uint64_t Xi[2]={0,0};
                gcm_ghash_avx(Xi, chunks[i].Htable, chunks[i].out, chunks[i].blocks*16);
                memcpy(chunks[i].Xi, Xi, 16);
            }
        }
